source('mp10_immune_endothelial_mechanisms_v1/scripts/common.R');plan<-rd('model_plan.tsv');ms<-rd('model_status.tsv');e<-rd('complete_candidate_evidence.tsv.gz');g<-rd('gsea_results.tsv.gz');ns<-rd('nichenet_analysis_status.tsv');net<-fread(file.path(REF,'collectri.tsv'));ac<-rd('activity_associations.tsv.gz')
# Keep all ligands; summarize prespecified LODO directions without a composite score.
for(h in c('H50','H10','H05')){
 ids<-plan[kind=='Epi'&target==h&min_cells==50&patient=='main'&subset=='own'&omit_dataset!='none',model_id];parts<-lapply(ids,function(id){f<-tb(paste0('de/',id,'.tsv.gz'));if(!file.exists(f))return(NULL);z<-fread(f);z[,model_id:=id];z});d<-rbindlist(parts);z<-d[,.(LODO_n_tested=.N,LODO_n_positive=sum(logFC>0),LODO_n_negative=sum(logFC<0),LODO_n_q05=sum(FDR<.05),LODO_min_logFC=min(logFC),LODO_max_logFC=max(logFC)),by=.(ligand=gene)];setnames(z,setdiff(names(z),'ligand'),paste0(h,'_',setdiff(names(z),'ligand')));old<-intersect(setdiff(names(z),'ligand'),names(e));if(length(old))e[,(old):=NULL];e<-merge(e,z,by='ligand',all.x=TRUE)
}
for(r in unique(e$receiver)){
 id<-plan[primary&kind=='receiver'&target==r,model_id];gg<-g[model_id==id&library=='Hallmark'&mask=='Full'&padj<.05][order(padj)];nss<-ns[model_id==id&detection_threshold==.1&target_direction=='union'];e[receiver==r,`:=`(receiver_model_reason=ms[model_id==id,reason],receiver_Hallmark_q05=if(ms[model_id==id,status]=='completed')nrow(gg)else NA_integer_,receiver_Hallmark_programs=if(nrow(gg))paste(paste0(gg$pathway,':',ifelse(gg$NES>0,'positive','negative')),collapse=';')else NA_character_,NicheNet_union_status=nss$status,NicheNet_union_reason=nss$reason,NicheNet_union_targets=nss$n_targets,NicheNet_mapping_reason=if('mapping_reason'%in%names(nss))nss$mapping_reason else NA_character_)]
}
e[,`:=`(NicheNet_activity_receptor_branch_specific=FALSE,branch_specific_NicheNet_support='not_identifiable_from_ligand_target_prior',receptor_primary_detection_pass=ifelse(is.na(receptor_median_detection),NA,receptor_median_detection>=.1))];put(e,'complete_candidate_evidence.tsv.gz');put(e[(ligand%in%c('NECTIN2','PVR')&receptor%in%c('TIGIT','PVRIG','CD226')&receiver%in%c('Treg','Tfh/CXCL13-like'))|(ligand%in%c('VEGFA','VEGFB','VEGFC','PGF','ANGPT1','ANGPT2')&receptor%in%c('FLT1','KDR','FLT4','NRP1','NRP2','TEK')&receiver%in%c('Arterial EC','Capillary EC'))],'key_axis_evidence.tsv')
# Specific prior TF-to-ligand edges are separate from shared downstream targets.
candidates<-c('NECTIN2','PVR','VEGFA','VEGFB','VEGFC','PGF');z<-net[target%in%candidates];setnames(z,c('source','target'),c('TF','ligand'));act<-ac[resource=='CollecTRI'&model_id%in%plan[primary&kind=='Epi',model_id],.(model_id,mask,TF=source,TF_activity_effect=activity_effect,TF_sample_p=sample_model_p,TF_sample_q=sample_model_q)];z<-merge(z,act,by='TF',allow.cartesian=TRUE,all.x=TRUE);put(z,'Epi_TF_candidate_ligand_prior_edges.tsv')
# Explicit second-seed coverage per preselected TF; no recovered edges is not a negative result when no motif regulon exists.
ss<-list();for(lin in c('Epi','T_lineage','Endothelial')){kf<-tb(paste0('scenic_',lin,'_key_TF_selection.tsv'));ef<-tb(paste0('scenic_',lin,'_connection_seed_stability.tsv.gz'));if(!file.exists(kf)||!file.exists(ef))next;k<-rd(paste0('scenic_',lin,'_key_TF_selection.tsv'));ed<-fread(ef);for(tf in unique(k$source)){x<-ed[TF==tf];xe<-x[seed_comparison_evaluable==TRUE];xp<-xe[is.finite(importance_seed123)&is.finite(importance_seed456)&importance_seed123>0&importance_seed456>0];rho<-if(nrow(xp)>=3&&sd(xp$importance_seed123)>0&&sd(xp$importance_seed456)>0)cor(xp$importance_seed123,xp$importance_seed456,method='spearman')else NA_real_;ss[[paste(lin,tf)]]<-data.table(lineage=lin,TF=tf,n_motif_edges=nrow(x),n_self_target_members=sum(x$self_target),n_evaluable_GRN_edges=nrow(xe),n_recovered_seed456=if(nrow(xe))sum(xe$recovered_seed456)else NA_integer_,recovery_fraction=if(nrow(xe))mean(xe$recovered_seed456)else NA_real_,n_positive_weight_pairs=nrow(xp),importance_spearman=rho,status=if(nrow(xe))'completed'else'not_evaluable',reason=if(nrow(xe))'key non-self GRN connections only'else if(nrow(x))'no_evaluable_nonself_GRN_edges'else'preselected_TF_has_no_motif_pruned_regulon')}};if(length(ss))put(rbindlist(ss),'scenic_second_seed_coverage.tsv')
# Dataset omission is informative only if the omitted dataset contributed to the corresponding main model.
mem<-rd('model_membership.tsv.gz');cov<-copy(plan);cov[,omission_changes_main_membership:=NA];for(i in which(cov$omit_dataset!='none')){p<-cov[i];mid<-plan[primary&kind==p$kind&target==p$target,model_id];cov[i,omission_changes_main_membership:=omit_dataset%in%mem[model_id%in%mid,dataset]]};cov[,`:=`(n_profiles_added_vs_main=NA_integer_,n_profiles_removed_vs_main=NA_integer_,identical_profiles_to_main=NA,exposure_changed_vs_main=exposure!='Q50')];for(i in seq_len(nrow(cov))){row<-cov[i];mid<-plan[primary&kind==row$kind&target==row$target,model_id];baseids<-mem[model_id%in%mid,profile_id];these<-mem[model_id==row$model_id,profile_id];if(length(these)&&length(baseids))cov[i,`:=`(n_profiles_added_vs_main=length(setdiff(these,baseids)),n_profiles_removed_vs_main=length(setdiff(baseids,these)),identical_profiles_to_main=setequal(these,baseids))]};put(cov,'model_sensitivity_interpretation.tsv')
put(mem[,.(n_specimens=uniqueN(sample_uid),n_recorded_patient_units=uniqueN(patient_uid_recorded),n_profiles=.N,total_cells=sum(n_cells)),by=.(model_id,dataset)],'model_dataset_coverage.tsv');cat('EVIDENCE DETAILS COMPLETE\n')
